// Simple Lead Scoring Test
const leadData = $input.item.json;

// Calculate lead score
let score = 0;
const projectType = (leadData.projectType || '').toLowerCase();
const timeline = (leadData.timeline || '').toLowerCase();
const location = (leadData.location || '').toLowerCase();

// Project type scoring
if (projectType.includes('commercial')) score += 35;
if (projectType.includes('urgent')) score += 25;
if (projectType.includes('basement')) score += 20;
if (projectType.includes('installation')) score += 15;

// Timeline urgency
if (timeline.includes('urgent') || timeline.includes('asap')) score += 25;
if (timeline.includes('this week')) score += 20;
if (timeline.includes('this month')) score += 15;

// Location premium
if (location.includes('kitchener') || location.includes('waterloo')) score += 10;
if (location.includes('toronto')) score += 15;

// Budget estimation
const sqft = parseInt(leadData.squareFootage) || 0;
const estimatedValue = sqft * 3;
if (estimatedValue > 10000) score += 30;
else if (estimatedValue > 5000) score += 25;
else if (estimatedValue > 2000) score += 20;

// Determine priority
let priority = 'low';
let estimatedBudget = '$500-1000';
if (score >= 60) {
  priority = 'urgent';
  estimatedBudget = '$2000-5000+';
} else if (score >= 40) {
  priority = 'high';
  estimatedBudget = '$1000-2500';
} else if (score >= 25) {
  priority = 'medium';
  estimatedBudget = '$500-1500';
}

return {
  json: {
    ...leadData,
    leadScore: score,
    priority: priority,
    estimatedValue: estimatedBudget,
    timestamp: new Date().toISOString(),
    testResult: `✅ LEAD SCORED: ${score} points - ${priority.toUpperCase()} priority - ${estimatedBudget} estimated value`
  }
};

